#include <stdlib.h>
#include <string.h>

// Assuming the structure definition for ExprDef:
typedef struct {
    int *keysym;
    int keysym_len;
    int *map;
    int map_len;
} ExprDef;

ExprDef* append_keysym_list(ExprDef *expr, ExprDef *append) {
    // Check for null pointers
    if (!expr || !append) {
        return expr;
    }

    // Calculate new lengths
    int new_keysym_len = expr->keysym_len + append->keysym_len;
    int new_map_len = expr->map_len + append->map_len;

    // Allocate new keysym array
    int *new_keysym = (int*)malloc(new_keysym_len * sizeof(int));
    if (!new_keysym) {
        return expr; // Memory allocation failed
    }

    // Allocate new map array
    int *new_map = (int*)malloc(new_map_len * sizeof(int));
    if (!new_map) {
        free(new_keysym);
        return expr; // Memory allocation failed
    }

    // Copy existing keysym and map data
    memcpy(new_keysym, expr->keysym, expr->keysym_len * sizeof(int));
    memcpy(new_keysym + expr->keysym_len, append->keysym, append->keysym_len * sizeof(int));

    memcpy(new_map, expr->map, expr->map_len * sizeof(int));
    memcpy(new_map + expr->map_len, append->map, append->map_len * sizeof(int));

    // Free old memory
    free(expr->keysym);
    free(expr->map);

    // Update expr with new data
    expr->keysym = new_keysym;
    expr->keysym_len = new_keysym_len;
    expr->map = new_map;
    expr->map_len = new_map_len;

    // Free the append structure
    free(append->keysym);
    free(append->map);
    free(append);

    return expr;
}
